functions.propSimulation:
function propSimulation(){const R=pool(),out=$('adv-p-summary');if(R.length<10){out.innerHTML='<b class="text-rose-700">Cần ≥ 10 lệnh đủ R, hãy vào nhật ký kiểm tra 1R trước.</b>';return;}const size=Math.max(1000,num('adv-p-size',1e5)),fee=Math.max(0,num('adv-p-fee',500)),target=range(num('adv-p-target',8)/100,.01,1),ml=range(num('adv-p-maxloss',10)/100,.01,.95),daily=range(num('adv-p-daily',5)/100,0,.95),f=range(num('adv-p-risk',.5)/100,.0001,.05),split=range(num('adv-p-split',80)/100,0,1),tpd=range(Math.round(num('adv-p-tpd',2)),1,30),h=range(Math.round(num('adv-p-horizon',120)),10,1000),N=range(Math.round(num('adv-p-runs',1000)),100,3000),trail=$('adv-p-ddmode').value==='trailing',rng=sampleRng(num('adv-p-seed',42));let win=0,fail=0,timeout=0,spans=[],outcomes=[];for(let j=0;j<N;j++){let eq=1,pk=1,day=1,status='timeout';for(let i=0;i<h;i++){if(i%tpd===0)day=eq;const r=R[Math.floor(rng()*R.length)];eq=Math.max(0,eq*(1+f*r));pk=Math.max(pk,eq);const floor=trail?Math.max(1-ml,pk-ml):1-ml;if(eq<=floor||(daily>0&&eq<=day*(1-daily))){status='fail';spans.push(i+1);break;}if(eq>=1+target){status='pass';spans.push(i+1);break;}}if(status==='pass')win++;else if(status==='fail')fail++;else timeout++;outcomes.push(eq);}
 const pass=win/N,payoutHyp=size*target*split,expectedHyp=pass*payoutHyp-fee;
 out.innerHTML='<div class="grid grid-cols-2 gap-2">'+card('Xác suất đạt target',percentage(pass))+card('Chạm giới hạn lỗ',percentage(fail/N))+card('Hết '+h+' lệnh',percentage(timeout/N))+card('Lệnh kết thúc (trung vị)',F(quant(spans,.5),0))+card('Payout giả định nếu được trả',cash(payoutHyp),'Không phải doanh thu đã nhận')+card('Giá trị kỳ vọng giả định / lượt',cash(expectedHyp),'Giả định payout = target × split')+'</div><p class="text-xs mt-2">'+N+' chiến dịch · '+R.length+' R lịch sử · '+(trail?'trailing':'static')+' DD · seed '+num('adv-p-seed',42)+'. Mô hình không bao gồm phí reset, slippage hay quy định consistency/payout/activation riêng. Không suy ra ROI thực tế từ chỉ số này.</p>';
 drawChart('adv-p-chart','bar',['Đạt target','Dính Max/Daily loss','Hết horizon'],[{data:[win,fail,timeout],backgroundColor:['#10b981','#f43f5e','#94a3b8']}],{scales:{y:{beginAtZero:true,ticks:{precision:0}}}});}
